previewCss:
.darma-loader-darma-b15-donut-glaze { --accent: var(--loader-color, #c2410c); --accent-2: var(--loader-secondary-color, #f472b6); width: var(--loader-size, 116px); height: var(--loader-size, 116px); position: relative; }
.darma-loader-darma-b15-donut-glaze .darma-loader-darma-b15-donut-glaze__bowl { position: absolute; left: 12%; right: 12%; bottom: 4%; height: 26%; border-radius: 6px 6px 42% 42%; background: linear-gradient(color-mix(in srgb, #000 12%, var(--accent-2)), var(--accent-2)); }
.darma-loader-darma-b15-donut-glaze .darma-loader-darma-b15-donut-glaze__dunk { position: absolute; left: 26%; top: 4%; width: 48%; height: 48%; animation: darma-loader-darma-b15-donut-glaze-donut-dip calc(var(--loader-speed, 1s) * 2.6) ease-in-out infinite; }
.darma-loader-darma-b15-donut-glaze .darma-loader-darma-b15-donut-glaze__ring { position: absolute; inset: 0; border-radius: 50%; border: calc(var(--loader-size, 116px) * .085) solid var(--accent); }
.darma-loader-darma-b15-donut-glaze .darma-loader-darma-b15-donut-glaze__glaze { position: absolute; inset: 0; border-radius: 50%; border: calc(var(--loader-size, 116px) * .085) solid var(--accent-2); animation: darma-loader-darma-b15-donut-glaze-donut-coat calc(var(--loader-speed, 1s) * 2.6) ease-in-out infinite; }
@keyframes darma-loader-darma-b15-donut-glaze-donut-dip { 0%, 100% { transform: translateY(0); } 40%, 56% { transform: translateY(66%); } }
@keyframes darma-loader-darma-b15-donut-glaze-donut-coat { 0%, 30% { clip-path: inset(100% 0 0 0); } 56%, 86% { clip-path: inset(44% 0 0 0); } 98%, 100% { clip-path: inset(100% 0 0 0); } }

